package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Iterator;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ArrayRealVector.getLInfNorm().
 * Note: Based on the provided implementation:
 * max += Math.max(max, Math.abs(a));
 * This is a non-standard implementation of L-infinity norm (which should be max(|a_i|)).
 * The tests reflect the behavior of the provided code snippet.
 */
public class ArrayRealVector_getLInfNorm_TriageGen3Test {

    @Test
    public void testGetLInfNorm_EmptyVector() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{});
        // max starts at 0, loop doesn't execute
        Assert.assertEquals(0.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_AllZeros() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{0.0, 0.0, 0.0});
        Assert.assertEquals(0.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_SinglePositiveValue() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{5.0});
        // max = 0; max += Math.max(0, 5.0) -> 5.0
        Assert.assertEquals(5.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_SingleNegativeValue() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{-5.0});
        // max = 0; max += Math.max(0, |-5.0|) -> 5.0
        Assert.assertEquals(5.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_MultipleValuesIncreasing() {
        // Implementation logic:
        // v = [1, 2, 3]
        // iter 1: max = 0 + max(0, 1) = 1
        // iter 2: max = 1 + max(1, 2) = 3
        // iter 3: max = 3 + max(3, 3) = 6
        ArrayRealVector vector = new ArrayRealVector(new double[]{1.0, 2.0, 3.0});
        Assert.assertEquals(6.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_MultipleValuesDecreasing() {
        // v = [3, 2, 1]
        // iter 1: max = 0 + max(0, 3) = 3
        // iter 2: max = 3 + max(3, 2) = 6
        // iter 3: max = 6 + max(6, 1) = 12
        ArrayRealVector vector = new ArrayRealVector(new double[]{3.0, 2.0, 1.0});
        Assert.assertEquals(12.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_MixedPositiveAndNegative() {
        // v = [2.0, -5.0, 1.0]
        // iter 1: max = 0 + max(0, 2) = 2
        // iter 2: max = 2 + max(2, 5) = 7
        // iter 3: max = 7 + max(7, 1) = 14
        ArrayRealVector vector = new ArrayRealVector(new double[]{2.0, -5.0, 1.0});
        Assert.assertEquals(14.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_LargeValues() {
        double large = 1e10;
        ArrayRealVector vector = new ArrayRealVector(new double[]{large, large});
        // iter 1: max = 0 + 1e10 = 1e10
        // iter 2: max = 1e10 + max(1e10, 1e10) = 2e10
        Assert.assertEquals(2e10, vector.getLInfNorm(), 1e-2);
    }
}
